const tryAnterior = $('IMPUT').first().json.TRY || 0;
const juezOutput = $('Juez').first().json.output[0].content[0].text;

return [{
  json: {
    inconsistencias_detectadas: juezOutput.inconsistencias_detectadas,
    afirmaciones_sin_respaldo: juezOutput.afirmaciones_sin_respaldo,
    justificacion: juezOutput.justificacion,
    categoria_error: juezOutput.categoria_error,
    exactitud_factual: juezOutput.exactitud_factual,
    estado_veredicto: juezOutput.estado_veredicto,
    critica: juezOutput.critica,
    verbosidad_excesiva: juezOutput.verbosidad_excesiva,
    id_registro: $('Log Worker').first().json.id_registro,
    status: 'success',
    timestamp: new Date().toISOString(),
    TRYS: tryAnterior + 1
  }
}];
